import { ChangeDetectionStrategy, Component, input } from '@angular/core';

@Component({
  selector: 'aevko-spinner',
  standalone: true,
  template: '<span class="ring" aria-hidden="true"></span>',
  styleUrl: './spinner.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    role: 'status',
    '[attr.aria-label]': 'label()',
    '[style.--aevko-spinner-size]': 'size()',
  },
})
export class AevkoSpinner {
  readonly label = input('Loading');
  readonly size = input('1rem');
}

:host {
  display: inline-flex;
  line-height: 0;
}
.ring {
  animation: aevko-spin 700ms linear infinite;
  border: 2px solid currentcolor;
  border-right-color: transparent;
  border-radius: 50%;
  display: block;
  height: var(--aevko-spinner-size, 1rem);
  width: var(--aevko-spinner-size, 1rem);
}
@keyframes aevko-spin {
  to {
    transform: rotate(1turn);
  }
}
@media (prefers-reduced-motion: reduce) {
  .ring {
    animation-duration: 2s;
  }
}
